package com.bank.core;

// One field of every primitive type on a realistic bank record.
public class AccountRecord {
    byte riskCode;        // tiny status code (-128..127)
    short branchId;       // small id (-32768..32767)
    int txnCount;         // normal count, default integer type
    long accountSeq;      // very large sequence, needs L suffix
    float interestRatio;  // single precision, needs f suffix (NOT money)
    double scoreFactor;   // double precision (NOT money)
    char accountType;     // single letter, e.g. 'S' for savings
    boolean active;       // yes/no flag

    // Fields left uninitialized demonstrate default values.
    public AccountRecord() { }

    public AccountRecord(byte riskCode, short branchId, int txnCount, long accountSeq,
                         float interestRatio, double scoreFactor, char accountType, boolean active) {
        this.riskCode = riskCode;
        this.branchId = branchId;
        this.txnCount = txnCount;
        this.accountSeq = accountSeq;
        this.interestRatio = interestRatio;
        this.scoreFactor = scoreFactor;
        this.accountType = accountType;
        this.active = active;
    }
}
