package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class PrimitiveShowcase {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Rajesh's savings account filled with every primitive type.
        AccountRecord rajesh = new AccountRecord(
            (byte) 2, (short) 101, 37, 9876543210L,
            0.5f, 3.14159d, 'S', true);

        log.info("Eight primitive data types on one bank record:");
        log.info(() -> "byte  riskCode     = " + rajesh.riskCode
                       + "  (range " + Byte.MIN_VALUE + ".." + Byte.MAX_VALUE + ")");
        log.info(() -> "short branchId     = " + rajesh.branchId
                       + "  (range " + Short.MIN_VALUE + ".." + Short.MAX_VALUE + ")");
        log.info(() -> "int   txnCount     = " + rajesh.txnCount
                       + "  (range " + Integer.MIN_VALUE + ".." + Integer.MAX_VALUE + ")");
        log.info(() -> "long  accountSeq   = " + rajesh.accountSeq
                       + "  (range " + Long.MIN_VALUE + ".." + Long.MAX_VALUE + ")");
        log.info(() -> "float interestRatio= " + rajesh.interestRatio);
        log.info(() -> "double scoreFactor = " + rajesh.scoreFactor);
        log.info(() -> "char  accountType  = " + rajesh.accountType
                       + "  (numeric code " + (int) rajesh.accountType + ")");
        log.info(() -> "boolean active     = " + rajesh.active);

        // Default values of an uninitialized record.
        AccountRecord blank = new AccountRecord();
        log.info("Default values of uninitialized primitive fields:");
        log.info(() -> "byte=" + blank.riskCode + " short=" + blank.branchId
                       + " int=" + blank.txnCount + " long=" + blank.accountSeq);
        log.info(() -> "float=" + blank.interestRatio + " double=" + blank.scoreFactor
                       + " char=[" + (int) blank.accountType + "] boolean=" + blank.active);

        // Why double is WRONG for money.
        double doubleMoney = 0.1 + 0.2;
        log.warning(() -> "double 0.1 + 0.2 = " + doubleMoney + "  (NOT 0.3 — rounding error)");
        BigDecimal exact = new BigDecimal("0.1").add(new BigDecimal("0.2"));
        log.info(() -> "BigDecimal 0.1 + 0.2 = " + exact + "  (exact — use for rupees)");
    }
}
